declare(strict_types=1);require_once __DIR__.'/../config.php';require_once __DIR__.'/../lib/TicketAttachments.php';require_once __DIR__.'/lib/Portal.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'support');$id=(int)($_GET['id']??0);[$scope,$params]=rxp_customer_scope($ctx,'u');[$ph,$ids]=rxp_in($ctx['scope_ids']);$q=$pdo->prepare("SELECT a.* FROM reseller_ticket_attachments a JOIN support_message sm ON sm.Tracking=a.tracking JOIN user u ON u.id=sm.iduser WHERE a.id=? AND a.reseller_id IN ($ph) AND $scope LIMIT 1");$q->execute(array_merge([$id],$ids,$params));$a=$q->fetch(PDO::FETCH_ASSOC);if(!$a){http_response_code(404);exit;}$path=RedFoxTicketAttachments::absolute(dirname(__DIR__),(string)$a['storage_name']);header('Content-Type: '.(string)$a['mime_type']);header('Content-Length: '.filesize($path));header('Content-Disposition: attachment; filename="'.rawurlencode((string)$a['original_name']).'"');header('X-Content-Type-Options: nosniff');header('Cache-Control: private, no-store');$f=fopen($path,'rb');while(!feof($f)){echo fread($f,1048576);flush();}fclose($f);
